import{_ as r,o as a,c as e,a2 as o}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"🙏 鸣谢","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"credits.md","filePath":"credits.md"}'),l={name:"credits.md"};function i(n,t,d,h,s,c){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="🙏-鸣谢" tabindex="-1">🙏 鸣谢 <a class="header-anchor" href="#🙏-鸣谢" aria-label="Permalink to &quot;🙏 鸣谢&quot;">​</a></h1><p>EmuTrain 的诞生离不开众多开发者、数据提供方与社区伙伴的支持。在此向所有贡献者致以诚挚的感谢！</p><hr><h2 id="数据提供方" tabindex="-1">数据提供方 <a class="header-anchor" href="#数据提供方" aria-label="Permalink to &quot;数据提供方&quot;">​</a></h2><p>没有以下平台的数据支撑，EmuTrain 将无法运行。感谢他们为铁路爱好者社区所作的贡献：</p><h3 id="🚂-rail-re" tabindex="-1">🚂 Rail.re <a class="header-anchor" href="#🚂-rail-re" aria-label="Permalink to &quot;🚂 Rail.re&quot;">​</a></h3><blockquote><p>一个专注中国动车组信息的第三方查询平台，提供动车组交路与车次数据。</p></blockquote><ul><li>网站：<a href="https://rail.re/" target="_blank" rel="noreferrer">https://rail.re/</a></li><li>用途：车次查询、动车组交路查询</li></ul><hr><h3 id="🚄-railgo" tabindex="-1">🚄 RailGo <a class="header-anchor" href="#🚄-railgo" aria-label="Permalink to &quot;🚄 RailGo&quot;">​</a></h3><blockquote><p>提供全面铁路信息的第三方数据平台，支持动车组与车次的多维度查询。</p></blockquote><ul><li>网站：<a href="https://railgo.dev/android.html" target="_blank" rel="noreferrer">https://railgo.dev/</a></li><li>用途：车次查询、动车组交路查询</li></ul><hr><h3 id="🏭-moefactory" tabindex="-1">🏭 MoeFactory <a class="header-anchor" href="#🏭-moefactory" aria-label="Permalink to &quot;🏭 MoeFactory&quot;">​</a></h3><blockquote><p>铁路综合数据平台，提供车站大屏、车号查询、时刻查询等多项服务。</p></blockquote><ul><li>网站：<a href="https://sharyou.moefactory.com/" target="_blank" rel="noreferrer">https://sharyou.moefactory.com/</a> · <a href="https://rail.moefactory.com/" target="_blank" rel="noreferrer">https://rail.moefactory.com/</a></li><li>用途：车站大屏、车号查询、车次时刻、线路走向图</li></ul><hr><h3 id="🏛️-passearch" tabindex="-1">🏛️ Passearch <a class="header-anchor" href="#🏛️-passearch" aria-label="Permalink to &quot;🏛️ Passearch&quot;">​</a></h3><blockquote><p>集成动车组、机车、车辆的一站式查询平台。</p></blockquote><ul><li>网站：<a href="https://emu.passearch.info/" target="_blank" rel="noreferrer">https://emu.passearch.info/</a></li><li>用途：列车配属</li></ul><hr><h3 id="📸-动车组图鉴-china-emu-cn" tabindex="-1">📸 动车组图鉴（china-emu.cn） <a class="header-anchor" href="#📸-动车组图鉴-china-emu-cn" aria-label="Permalink to &quot;📸 动车组图鉴（china-emu.cn）&quot;">​</a></h3><blockquote><p>专注中国动车组的图片数据库，收录各型动车组的外观图片与特殊涂装。</p></blockquote><ul><li>网站：<a href="https://china-emu.cn/" target="_blank" rel="noreferrer">https://china-emu.cn/</a></li><li>用途：动车图鉴功能的图片来源</li></ul><hr><h2 id="线路数据支持" tabindex="-1">线路数据支持 <a class="header-anchor" href="#线路数据支持" aria-label="Permalink to &quot;线路数据支持&quot;">​</a></h2><h3 id="🌊-黄河铁路网-·-jprailfan-com" tabindex="-1">🌊 黄河铁路网 · jprailfan.com <a class="header-anchor" href="#🌊-黄河铁路网-·-jprailfan-com" aria-label="Permalink to &quot;🌊 黄河铁路网 · jprailfan.com&quot;">​</a></h3><blockquote><p>黄河铁路网（jprailfan.com）提供了大量中国铁路线路信息，为 EmuTrain 的线路功能提供了宝贵的数据参考与支持。</p></blockquote><ul><li>网站：<a href="https://www.jprailfan.com/" target="_blank" rel="noreferrer">https://www.jprailfan.com/</a></li><li>感谢黄河铁路网的铁路爱好者们整理分享大量线路资料！</li></ul><hr><h2 id="友情-app" tabindex="-1">友情 APP <a class="header-anchor" href="#友情-app" aria-label="Permalink to &quot;友情 APP&quot;">​</a></h2><p>感谢以下优秀应用为铁路爱好者社区作出的贡献，EmuTrain 与它们并肩同行：</p><table tabindex="0"><thead><tr><th>APP</th><th>链接</th><th>简介</th></tr></thead><tbody><tr><td><strong>路路通</strong></td><td><a href="https://sj.qq.com/appdetail/com.lltskb.lltskb" target="_blank" rel="noreferrer">sj.qq.com</a></td><td>国铁综合出行 APP</td></tr><tr><td><strong>Rail.re 动车组查询</strong></td><td><a href="https://rail.re/" target="_blank" rel="noreferrer">rail.re</a></td><td>动车组信息查询网站</td></tr><tr><td><strong>RailGo</strong></td><td><a href="https://railgo.dev/android.html" target="_blank" rel="noreferrer">railgo.dev</a></td><td>铁路信息查询 APP</td></tr><tr><td><strong>MoeFactory 车箱</strong></td><td><a href="https://sharyou.moefactory.com/" target="_blank" rel="noreferrer">sharyou.moefactory.com</a></td><td>铁路综合数据平台</td></tr><tr><td><strong>动车组图鉴</strong></td><td><a href="https://china-emu.cn/" target="_blank" rel="noreferrer">china-emu.cn</a></td><td>动车组图片数据库</td></tr></tbody></table><hr><h2 id="开源技术" tabindex="-1">开源技术 <a class="header-anchor" href="#开源技术" aria-label="Permalink to &quot;开源技术&quot;">​</a></h2><p>EmuTrain 基于以下开源技术构建，感谢所有开源社区的贡献者：</p><table tabindex="0"><thead><tr><th>技术</th><th>用途</th></tr></thead><tbody><tr><td><strong>Flutter</strong></td><td>跨平台 UI 框架</td></tr><tr><td><strong>Material You (Material 3)</strong></td><td>设计规范</td></tr><tr><td><strong>dynamic_color</strong></td><td>Android 12+ 莫奈取色支持</td></tr><tr><td><strong>provider</strong></td><td>状态管理</td></tr><tr><td><strong>http</strong></td><td>网络请求</td></tr><tr><td><strong>shared_preferences</strong></td><td>本地持久化存储</td></tr><tr><td><strong>path_provider</strong></td><td>文件路径管理</td></tr><tr><td><strong>url_launcher</strong></td><td>外部链接跳转</td></tr></tbody></table><hr><h2 id="社区用户" tabindex="-1">社区用户 <a class="header-anchor" href="#社区用户" aria-label="Permalink to &quot;社区用户&quot;">​</a></h2><p>感谢每一位使用 EmuTrain 的铁路爱好者！你们的反馈、Bug 报告和功能建议是 EmuTrain 持续进步的最大动力。</p><p>特别感谢在 <a href="/qq.html">QQ 群（667933194）</a> 中积极反馈的用户朋友们 🚄</p><hr><h2 id="开发者" tabindex="-1">开发者 <a class="header-anchor" href="#开发者" aria-label="Permalink to &quot;开发者&quot;">​</a></h2><div style="background:var(--vp-c-bg-soft);border:1px solid var(--vp-c-border);border-radius:12px;padding:20px 24px;margin-top:16px;"><div style="display:flex;align-items:center;gap:16px;"><div style="font-size:48px;">👨‍💻</div><div><div style="font-size:1.2em;font-weight:700;margin-bottom:4px;">银狼 · CrYinLang</div><div style="color:var(--vp-c-text-2);font-size:0.95em;">EmuTrain 主开发者</div><div style="margin-top:8px;display:flex;gap:12px;flex-wrap:wrap;"><a href="https://github.com/CrYinLang" target="_blank" style="color:var(--vp-c-brand-1);">GitHub →</a><a href="https://gitee.com/CrYinLang" target="_blank" style="color:var(--vp-c-brand-1);">Gitee →</a><a href="https://www.douyin.com/user/MS4wLjABAAAA-bZxFhm96BhUle209c1gQ5HskPw4y-olT2PwOYevJ6fSkkHmIV23EuGfjaq1xHCx" target="_blank" style="color:var(--vp-c-brand-1);">抖音 →</a><a href="https://qm.qq.com/q/AJ71AadV5K" target="_blank" style="color:var(--vp-c-brand-1);">QQ 群 →</a></div></div></div></div><hr><p><em>再次感谢所有为铁路爱好者社区默默付出的朋友们。乘风破浪，一路向前！🚄💨</em></p>',46)])])}const m=r(l,[["render",i]]);export{u as __pageData,m as default};
